export function createPerson(child=false,police=false){const root=new T.Group();const skin=new T.MeshStandardMaterial({color:'#c89b77',roughness:.95});const shirt=new T.MeshStandardMaterial({color:police?'#326187':child?'#f0b448':'#e5e0d6',roughness:1});const pants=new T.MeshStandardMaterial({color:'#354c60',roughness:1});const s=child?.7:1;const head=new T.Mesh(new T.SphereGeometry(.135,10,8),skin);head.position.y=1.58;root.add(head);const hair=new T.Mesh(new T.SphereGeometry(.14,10,8,0,Math.PI*2,0,Math.PI*.55),black);hair.position.y=1.61;root.add(hair);box(root,shirt,0,1.19,0,.36,.53,.23);if(child){box(root,new T.MeshStandardMaterial({color:'#9d3731'}),0,1.2,.18,.3,.38,.15);const hat=new T.Mesh(new T.CylinderGeometry(.2,.2,.035,14),shirt);hat.position.y=1.7;root.add(hat);}
 const limbs=[];for(const x of [-.12,.12]){const leg=new T.Group();leg.position.set(x,.94,0);box(leg,pants,0,-.36,0,.13,.7,.15);box(leg,black,0,-.75,-.055,.16,.12,.27);root.add(leg);limbs.push(leg);}for(const x of [-.24,.24]){const arm=new T.Group();arm.position.set(x,1.4,0);box(arm,shirt,0,-.14,0,.12,.29,.13);box(arm,skin,0,-.37,0,.09,.2,.1);root.add(arm);limbs.push(arm);}if(police){box(root,chrome,0,1.33,-.125,.25,.05,.025);const cap=new T.Mesh(new T.CylinderGeometry(.155,.155,.09,12),shirt);cap.position.y=1.75;root.add(cap);box(root,black,0,1.71,-.12,.27,.025,.15);}root.scale.setScalar(s);return {root,limbs,child};}
export function createTram(){const root=new T.Group(),green=new T.MeshStandardMaterial({color:'#305e4f',metalness:.3,roughness:.4}),cream=new T.MeshStandardMaterial({color:'#dfd8bd',roughness:.55});box(root,green,0,1,0,2.35,1.5,11);box(root,cream,0,2.36,0,2.35,1.15,10.9);box(root,black,0,3.02,0,2.45,.16,11.2);for(const s of [-1,1]){for(let z=-4.3;z<4.8;z+=1.22)box(root,glass,s*1.185,2.35,z,.035,.86,.96);box(root,glass,0,2.34,s*5.47,1.99,.81,.025);box(root,light,0,1.18,s*5.52,.6,.14,.04);}box(root,chrome,0,3.55,0,.08,1.1,.08);const pant=box(root,chrome,0,3.83,0,1.9,.04,.05);pant.rotation.z=.1;return {root};}
